  + VATNumber : string
}

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class Single {}

class Hit {}

class Album {
}

class AlbumTrack {
  + TrackNumber : int
}

Artist "1" -- "*" Song
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" AlbumTrack
AlbumTrack "*" -- "1" Hit

Single "*" -- "1" Song
Hit "*" -- "1" Song

@enduml

